CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, platform_admin INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE plans(id TEXT PRIMARY KEY, name TEXT NOT NULL, stripe_price_id TEXT, property_limit INTEGER NOT NULL DEFAULT 100, member_limit INTEGER NOT NULL DEFAULT 20, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE companies(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT '#197566', stripe_account_id TEXT UNIQUE, stripe_customer_id TEXT UNIQUE, plan_id TEXT REFERENCES plans(id), subscription_status TEXT NOT NULL DEFAULT 'unconfigured', reminder_days TEXT NOT NULL DEFAULT '[-5,0,3]', email_template TEXT NOT NULL DEFAULT 'A renda de {{amount}} vence em {{date}}. Consulte o portal para pagar.', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memberships(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('ADMIN','MANAGER','FINANCE','TECHNICIAN','OWNER','RESIDENT')), active INTEGER NOT NULL DEFAULT 1, UNIQUE(company_id,user_id));
CREATE TABLE sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, csrf TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reset_tokens(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE properties(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), parent_id TEXT, owner_id TEXT REFERENCES users(id), name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('BUILDING','APARTMENT','ROOM','COMMON')), address TEXT NOT NULL, city TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', bedrooms INTEGER NOT NULL DEFAULT 1, area INTEGER NOT NULL DEFAULT 0, rent_cents INTEGER NOT NULL CHECK(rent_cents>=0), published INTEGER NOT NULL DEFAULT 0, photos TEXT NOT NULL DEFAULT '[]', amenities TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id), FOREIGN KEY(company_id,parent_id) REFERENCES properties(company_id,id));
CREATE TABLE contacts(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), user_id TEXT REFERENCES users(id), name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'LEAD', tags TEXT NOT NULL DEFAULT '[]', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id));
CREATE TABLE leads(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), contact_id TEXT NOT NULL, property_id TEXT, stage TEXT NOT NULL DEFAULT 'NEW', source TEXT NOT NULL DEFAULT 'manual', notes TEXT NOT NULL DEFAULT '', visit_at TEXT, task TEXT NOT NULL DEFAULT '', task_due TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id), FOREIGN KEY(company_id,contact_id) REFERENCES contacts(company_id,id), FOREIGN KEY(company_id,property_id) REFERENCES properties(company_id,id));
CREATE TABLE contracts(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), property_id TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT, rent_cents INTEGER NOT NULL CHECK(rent_cents>0), charges_cents INTEGER NOT NULL DEFAULT 0 CHECK(charges_cents>=0), deposit_cents INTEGER NOT NULL DEFAULT 0 CHECK(deposit_cents>=0), due_day INTEGER NOT NULL DEFAULT 1 CHECK(due_day BETWEEN 1 AND 31), status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ENDED','CANCELLED')), notes TEXT NOT NULL DEFAULT '', template TEXT NOT NULL DEFAULT 'Contrato de arrendamento entre {{company}} e {{residents}}, relativo a {{property}}, com início em {{start}} e renda mensal de {{rent}}.', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id), FOREIGN KEY(company_id,property_id) REFERENCES properties(company_id,id), CHECK(end_date IS NULL OR end_date>=start_date));
CREATE TABLE contract_residents(company_id TEXT NOT NULL, contract_id TEXT NOT NULL, contact_id TEXT NOT NULL, PRIMARY KEY(contract_id,contact_id), FOREIGN KEY(company_id,contract_id) REFERENCES contracts(company_id,id), FOREIGN KEY(company_id,contact_id) REFERENCES contacts(company_id,id));
CREATE TABLE rent_changes(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, contract_id TEXT NOT NULL, effective_date TEXT NOT NULL, rent_cents INTEGER NOT NULL CHECK(rent_cents>0), UNIQUE(contract_id,effective_date), FOREIGN KEY(company_id,contract_id) REFERENCES contracts(company_id,id));
CREATE TABLE deposit_entries(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, contract_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('RECEIVED','RETURNED','DEDUCTED')), amount_cents INTEGER NOT NULL CHECK(amount_cents>0), reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id,contract_id) REFERENCES contracts(company_id,id));
CREATE TABLE inspections(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, contract_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('ENTRY','EXIT')), notes TEXT NOT NULL DEFAULT '', items TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id,contract_id) REFERENCES contracts(company_id,id));
CREATE TABLE charges(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, contract_id TEXT NOT NULL, period TEXT NOT NULL, due_date TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), confirmed INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(contract_id,period), UNIQUE(company_id,id), FOREIGN KEY(company_id,contract_id) REFERENCES contracts(company_id,id));
CREATE TABLE payments(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, charge_id TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), kind TEXT NOT NULL CHECK(kind IN ('PAYMENT','REFUND','ADJUSTMENT','DISPUTE','DISPUTE_WON')), method TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', external_id TEXT UNIQUE, idempotency_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id,charge_id) REFERENCES charges(company_id,id));
CREATE TABLE checkouts(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, charge_id TEXT NOT NULL, stripe_session_id TEXT UNIQUE, payment_intent TEXT, amount_cents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'CREATING', url TEXT, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id), FOREIGN KEY(company_id,charge_id) REFERENCES charges(company_id,id));
CREATE UNIQUE INDEX one_active_checkout ON checkouts(charge_id) WHERE status IN ('CREATING','OPEN','PROCESSING');
CREATE TABLE webhook_events(id TEXT PRIMARY KEY, company_id TEXT, type TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tickets(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, property_id TEXT NOT NULL, reporter_id TEXT NOT NULL REFERENCES users(id), assignee_id TEXT REFERENCES users(id), provider_id TEXT, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'OTHER', priority TEXT NOT NULL DEFAULT 'NORMAL', status TEXT NOT NULL DEFAULT 'NEW', due_at TEXT, scheduled_at TEXT, budget_cents INTEGER, budget_approved INTEGER NOT NULL DEFAULT 0, final_cost_cents INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id), FOREIGN KEY(company_id,property_id) REFERENCES properties(company_id,id), FOREIGN KEY(company_id,provider_id) REFERENCES contacts(company_id,id));
CREATE TABLE ticket_notes(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, ticket_id TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, internal INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id,ticket_id) REFERENCES tickets(company_id,id));
CREATE TABLE expenses(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, property_id TEXT NOT NULL, ticket_id TEXT, description TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), date TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id,property_id) REFERENCES properties(company_id,id), FOREIGN KEY(company_id,ticket_id) REFERENCES tickets(company_id,id));
CREATE TABLE conversations(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, property_id TEXT, subject TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id), FOREIGN KEY(company_id,property_id) REFERENCES properties(company_id,id));
CREATE TABLE participants(company_id TEXT NOT NULL, conversation_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(conversation_id,user_id), FOREIGN KEY(company_id,conversation_id) REFERENCES conversations(company_id,id));
CREATE TABLE messages(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, conversation_id TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id), FOREIGN KEY(company_id,conversation_id) REFERENCES conversations(company_id,id));
CREATE TABLE message_reads(message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES users(id), read_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(message_id,user_id));
CREATE TABLE notifications(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), user_id TEXT NOT NULL REFERENCES users(id), charge_id TEXT, title TEXT NOT NULL, body TEXT NOT NULL, email_status TEXT NOT NULL DEFAULT 'PENDING', is_read INTEGER NOT NULL DEFAULT 0, dedupe_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id,charge_id) REFERENCES charges(company_id,id));
CREATE TABLE jobs(id TEXT PRIMARY KEY, company_id TEXT, type TEXT NOT NULL, payload TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'PENDING', attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, locked_at TEXT, last_error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE documents(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, name TEXT NOT NULL, storage_path TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, size INTEGER NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE devices(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), user_id TEXT NOT NULL REFERENCES users(id), token TEXT NOT NULL, platform TEXT NOT NULL, UNIQUE(company_id,user_id,token));
CREATE TABLE audit(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), user_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_properties_company ON properties(company_id);
CREATE INDEX idx_contracts_property ON contracts(company_id,property_id,start_date,end_date);
CREATE INDEX idx_contacts_company ON contacts(company_id,user_id);
CREATE INDEX idx_charges_company ON charges(company_id,due_date);
CREATE INDEX idx_payments_charge ON payments(company_id,charge_id);
CREATE INDEX idx_tickets_company ON tickets(company_id,assignee_id,status);
CREATE INDEX idx_notifications_user ON notifications(company_id,user_id,is_read);
CREATE INDEX idx_jobs_pending ON jobs(status,available_at);
CREATE INDEX idx_docs_entity ON documents(company_id,entity_type,entity_id);
